// Level filter, then intake exclusions (lib-config). An alert whose level is
// missing or not numeric is not filtered here: pb-generic's normalizer parks it.
const alert = $('Intake input').first().json.alert;
const cfg = $input.first().json;
const rule = alert !== null && typeof alert === 'object' ? alert.rule : undefined;
const raw = rule !== null && typeof rule === 'object' ? rule.level : undefined;
const level = typeof raw === 'number' && Number.isInteger(raw) ? raw
  : typeof raw === 'string' && /^\d+$/.test(raw.trim()) ? Number(raw.trim()) : null;
const groups = rule !== null && typeof rule === 'object' && Array.isArray(rule.groups) ? rule.groups : [];
let decision = 'handoff';
let status = 'handed off to pb-generic';
if (level !== null && level < cfg.min_level) {
  decision = 'filtered';
  status = `filtered: level ${level} < ${cfg.min_level}`;
} else {
  const ex = cfg.intake_exclusions.find((e) => groups.includes(e.rule_group));
  if (ex) { decision = 'skipped'; status = `skipped: ${ex.label}`; }
}
return [{ json: {
  decision, status,
  wazuh_alert_id: typeof alert?.id === 'string' ? alert.id : null,
  rule_id: rule?.id ?? null, rule_level: level,
  alert, config: cfg, recv_execution_id: $execution.id,
} }];
